import importlib.util,json,os
from pathlib import Path
R=Path(__file__).resolve().parent
sp=importlib.util.spec_from_file_location('p',R/'pilot-authored.py');p=importlib.util.module_from_spec(sp);sp.loader.exec_module(p)
L='https://digmanclass.universiteitleiden.nl/glossary/';C='https://manuscript.ku.dk/about/glossary/';H='https://wiki.helsinki.fi/xwiki/bin/view/stemmatology/'
proofs={}
def pr(key,name,url,section,quote):
 f=R/'sources'/(name+'.html');a=p.Text();a.feed(f.read_text());t=' '.join(' '.join(a.parts).split());assert quote in t,quote
 proofs[key]={'sourceClass':'University manuscript research/collection educational publication, original institution page','title':name,'url':url,'rawCapture':'sources/'+f.name,'captureFormat':'HTML original bytes','captureMethod':'Complete HTTP200 curl --compressed response, preserved without alteration. Full relevant entry read in the original HTML.','locator':section,'passage':quote}
pr('palimpsest','leiden-glossary',L,'Palimpsest','Alternatively, you can take a book that is no longer used from your monastery’s library and scrape the text off its pages. You then simply reapply text of your own. Such recycling resulted in a ‘palimpsest’, which held a removed ‘lower text’ and a newer ‘upper text’.')
pr('palimpsest-extra','leiden-glossary',L,'Palimpsest','The ink of the reapplied text often does not stick to the page very well. Moreover, the older reading often shines through.')
pr('apograph','helsinki-apograph',H+'Apograph/','Main article','An apograph is a new manuscript produced by a copyist who is copying a text found in an earlier manuscript, an exemplar .')
pr('autograph','helsinki-autograph',H+'Autograph/','Main article','In manuscript studies, an autograph is a witness written by the author himself.')
pr('bifolium','leiden-glossary',L,'Bifolium','To create a bifolium, a sheet is folded in half (each half is called a ‘folium’, which consists of two ‘pages’, i.e. the front and back of the folium).')
pr('bifolium-quire','leiden-glossary',L,'Bifolium','If the quire is the building block of the medieval book, the bifolium is what defines the quire: four, five or six of them were bundled up and subsequently filled with text.')
pr('quire','leiden-glossary',L,'Quire','An extra folium could be added (called a singleton) or a leaf could be cut out.')
pr('codex','copenhagen-glossary',C,'codex','codex : from the Latin word meaning \'tree trunk\' meaning book')
pr('manicula','leiden-glossary',L,'Manicula','The manicula (Latin for ‘little hand’) was another means to do so. As with ‘nota-signs’, the actual form of the pointing finger varies considerably. Readers may have had their own unique design to distinguish their hands from those of other readers.')
pr('manicula-attention','leiden-glossary',L,'Manicula','With a nota-sign the reader expressed that a passage was noteworthy or deserved a closer read. The manicula (Latin for ‘little hand’) was another means to do so.')
pr('gloss-function','leiden-glossary',L,'Notes','When a passage prompted a response or an explanation, the reader could provide these in the form of a marginal gloss.')
pr('gloss-extra','leiden-glossary',L,'Gloss','Some of these notes (or glosses) were extensive, and the scribe had to extend the margins to accommodate them.')
pr('catchword','leiden-glossary',L,'Catchwords and Signatures','To make sure that each finished quire ended up in the correct order, the scribe often wrote the first words of the next quire in the lower margin of the last page he copied. These are called ‘catchwords’.')
pr('rubric','leiden-glossary',L,'Rubric','In manuscripts it was used for the rubric (from the Latin word for ‘red’). Placed at the outset of each chapter, rubrics provided the reader with an indication of what the following chapter was about.')
pr('colophon','leiden-glossary',L,'Scribal Colophon','Lucky for us, on occasion, scribes added a colophon to the book (almost always found on the last page). The colophon provides us with similar information now copied onto title pages. A scribe may state, for example, in which year he copied the book, where he lived, and, in some cases, even for whom the book was made.')
edits={
'middle-ages-palimpsest':{'prompt':'Какой термин в описании средневековой рукописи указывает именно на повторное использование пергамента после удаления прежнего текста?','answers':[{'text':'Апограф','note':'Апограф — новая рукопись, в которую переписчик перенёс текст из более ранней рукописи.'},{'text':'Палимпсест','note':'На повторно использованном листе новые чернила порой держались хуже, а старый текст просвечивал.'},{'text':'Автограф','note':'В изучении рукописей автографом называют текст, написанный рукой самого автора.'},{'text':'Экземпляр-образец','note':'Экземпляр-образец служит переписчику источником текста для изготовления новой копии.'}],'explanation':'Такую рукопись называют палимпсестом. Прежний текст удаляли с пергамента, чтобы записать на нём новый, поэтому исследователи различают нижний и верхний слои текста.'},
'middle-ages-codex':{'prompt':'Как называется двойной лист средневековой рукописи, полученный одним сгибанием листа пергамента и образующий четыре страницы?','answers':[{'text':'Фолий','note':'Фолий имеет лицевую и оборотную стороны, то есть две страницы.'},{'text':'Тетрадь','note':'В рукописную тетрадь могли добавить отдельный лист или удалить один из уже имевшихся.'},{'text':'Бифолий','note':'Для составления тетради обычно объединяли четыре, пять или шесть бифолиев.'},{'text':'Кодекс','note':'Латинское слово codex, обозначавшее книгу, связано со значением «ствол дерева».'}],'explanation':'Это бифолий: лист, сложенный вдвое. Он образует два фолия, каждый с лицевой и оборотной стороной, — всего четыре страницы.'},
'middle-ages-colophon':{'prompt':'Как назывался нарисованный на полях средневековой рукописи знак в виде руки с указующим пальцем, отмечавший важное место?','answers':[{'text':'Глосса','note':'Глосса на полях могла содержать отклик читателя или пояснение к тексту.'},{'text':'Кустода','note':'Кустода в конце тетради повторяла начальные слова следующей и помогала соблюдать порядок тетрадей при переплёте.'},{'text':'Рубрика','note':'Рубрика сообщала, о чём пойдёт речь в следующей главе; для неё часто использовали красный цвет.'},{'text':'Маникула','note':'Читатели могли рисовать манику́лы в собственной манере, чтобы отличать свои пометы от чужих.'}],'explanation':'Такой знак назывался маникулой — буквально «маленькой рукой». Он направлял внимание читателя к месту, заслуживавшему особого внимания.'},
'middle-ages-gloss':{'prompt':'Как называли пояснение к тексту, которое читатель средневековой рукописи записывал на её полях?','answers':[{'text':'Колофон','note':'В колофоне писец мог назвать год создания рукописи, место своего проживания или заказчика книги.'},{'text':'Кустода','note':'Кустода в конце тетради повторяла начальные слова следующей и помогала соблюдать порядок тетрадей при переплёте.'},{'text':'Рубрика','note':'Рубрика сообщала, о чём пойдёт речь в следующей главе; для неё часто использовали красный цвет.'},{'text':'Глосса','note':'Некоторые глоссы были столь пространными, что писцу приходилось расширять отведённые для них поля.'}],'explanation':'Такое пояснение называли глоссой. Оно дополняло основной текст и помогало читателю осмыслить отдельное место.'}}
